use vstd::prelude::*;

verus! {

    // Specification function returning true iff
    // the vector length is positive
    // and every character is a lowercase ASCII letter 'a'..'z'
    spec fn check_all_lowercase(v: &Vec<char>) -> bool {
        v.len() > 0 &&
        forall |i: usize| (i < v.len()) ==> ('a' <= v[i] && v[i] <= 'z')
    }

    fn solve(input: Vec<char>) -> Vec<char>
        ensures
            // output always length 1
            result.len() == 1 &&
            // output is either ['a'] or ['A']
            (result[0] == 'a' || result[0] == 'A') &&
            // output is ['a'] iff input is all lowercase
            (result[0] == 'a' <==> check_all_lowercase(&input))
    {
        // Handle empty input case
        if input.len() == 0 {
            return vec!['A'];
        }

        let mut all_lowercase = true;
        let mut i: usize = 0;

        while i < input.len()
            invariant
                i <= input.len(),
                input.len() > 0,
                all_lowercase <==> (forall |j: usize| (j < i) ==> ('a' <= input[j] && input[j] <= 'z')),
            decreases input.len() - i,
        {
            if input[i] < 'a' || input[i] > 'z' {
                all_lowercase = false;
            }
            i = i + 1;
        }

        assert(all_lowercase <==> check_all_lowercase(&input));

        if all_lowercase {
            vec!['a']
        } else {
            vec!['A']
        }
    }

}

